#!/usr/bin/env python3
"""Verify that known postcritical defects are generated by block lines."""

from __future__ import annotations
class VerificationError(RuntimeError):
    """Raised when an exact verifier condition fails."""


def require(condition, message):
    if not condition:
        raise VerificationError(str(message))


if not __debug__:
    raise RuntimeError(
        "Verifier refuses optimized execution; rerun without Python -O."
    )



import argparse
import hashlib
import itertools
import json
from collections import Counter, defaultdict
from math import comb
from pathlib import Path

from search_postcritical_interpolation_counterexamples import (
    compositions,
    product_mod,
)


ROOT = Path(__file__).resolve().parent
CERTIFICATE = ROOT / "postcritical_block_line_relation_space.json"


def rref(
    matrix: list[list[int]], prime: int
) -> tuple[list[list[int]], list[int]]:
    data = [[entry % prime for entry in row] for row in matrix]
    rows = len(data)
    columns = len(data[0]) if data else 0
    pivots: list[int] = []
    pivot_row = 0
    for column in range(columns):
        pivot = next(
            (
                row
                for row in range(pivot_row, rows)
                if data[row][column]
            ),
            None,
        )
        if pivot is None:
            continue
        data[pivot_row], data[pivot] = data[pivot], data[pivot_row]
        inverse = pow(data[pivot_row][column], prime - 2, prime)
        data[pivot_row] = [
            inverse * entry % prime for entry in data[pivot_row]
        ]
        for row in range(rows):
            if row == pivot_row:
                continue
            factor = data[row][column]
            if factor:
                data[row] = [
                    (data[row][index] - factor * data[pivot_row][index])
                    % prime
                    for index in range(columns)
                ]
        pivots.append(column)
        pivot_row += 1
        if pivot_row == rows:
            break
    return data, pivots


def rank_mod(matrix: list[list[int]], prime: int) -> int:
    return len(rref(matrix, prime)[1])


def nullspace_basis(
    matrix: list[list[int]], prime: int
) -> list[list[int]]:
    reduced, pivots = rref(matrix, prime)
    columns = len(matrix[0]) if matrix else 0
    pivot_set = set(pivots)
    free_columns = [
        column for column in range(columns) if column not in pivot_set
    ]
    basis = []
    for free in free_columns:
        vector = [0] * columns
        vector[free] = 1
        for row, pivot in enumerate(pivots):
            vector[pivot] = -reduced[row][free] % prime
        basis.append(vector)
    return basis


def transpose(matrix: list[list[int]]) -> list[list[int]]:
    if not matrix:
        return []
    return [list(column) for column in zip(*matrix)]


def locator_values(
    roots: tuple[int, ...],
    sources: tuple[int, ...],
    prime: int,
) -> list[int]:
    return [
        product_mod(((source - root) % prime for root in roots), prime)
        for source in sources
    ]


def line_key(
    prime: int,
    sources: tuple[int, ...],
    block: tuple[int, ...],
) -> tuple[tuple[int, ...], ...]:
    values = locator_values(block, sources, prime)
    inverse_values = [pow(value, prime - 2, prime) for value in values]
    rows = [
        inverse_values,
        [
            source * inverse_value % prime
            for source, inverse_value in zip(sources, inverse_values)
        ],
    ]
    reduced, pivots = rref(rows, prime)
    require(
        len(pivots) == 2,
        'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:120',
    )
    return tuple(tuple(row) for row in reduced[:2])


def evaluation_matrix(
    prime: int,
    sources: tuple[int, ...],
    selected: tuple[int, ...],
) -> tuple[list[tuple[int, ...]], list[list[int]]]:
    a = len(sources)
    degree = len(selected) - a + 2
    monomials = compositions(degree, a)
    labels = list(itertools.combinations(selected, a - 1))
    matrix = []
    for label in labels:
        coordinates = [
            pow(value, prime - 2, prime)
            for value in locator_values(label, sources, prime)
        ]
        scale = pow(coordinates[0], prime - 2, prime)
        coordinates = [
            coordinate * scale % prime for coordinate in coordinates
        ]
        matrix.append(
            [
                product_mod(
                    (
                        pow(coordinate, exponent, prime)
                        for coordinate, exponent in zip(
                            coordinates, exponents
                        )
                    ),
                    prime,
                )
                for exponents in monomials
            ]
        )
    return labels, matrix


def vertex_coordinates(
    prime: int,
    sources: tuple[int, ...],
    label: tuple[int, ...],
) -> list[int]:
    coordinates = [
        pow(value, prime - 2, prime)
        for value in locator_values(label, sources, prime)
    ]
    scale = pow(coordinates[0], prime - 2, prime)
    return [coordinate * scale % prime for coordinate in coordinates]


def rich_line_profile(
    prime: int,
    sources: tuple[int, ...],
    selected: tuple[int, ...],
) -> dict[str, int]:
    labels = list(
        itertools.combinations(selected, len(sources) - 1)
    )
    points = [
        vertex_coordinates(prime, sources, label) for label in labels
    ]
    canonical_keys = {
        line_key(prime, sources, block)
        for block in itertools.combinations(selected, len(sources))
    }
    line_points: dict[
        tuple[tuple[int, ...], ...], set[int]
    ] = defaultdict(set)
    for left, right in itertools.combinations(range(len(points)), 2):
        reduced, pivots = rref(
            [points[left], points[right]], prime
        )
        require(
            len(pivots) == 2,
            'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:195',
        )
        key = tuple(tuple(row) for row in reduced[:2])
        line_points[key].update((left, right))

    rich = {
        key: indices
        for key, indices in line_points.items()
        if len(indices) >= 3
    }
    canonical = [
        len(indices)
        for key, indices in rich.items()
        if key in canonical_keys
    ]
    noncanonical = [
        len(indices)
        for key, indices in rich.items()
        if key not in canonical_keys
    ]
    return {
        "rich_line_count": len(rich),
        "canonical_rich_line_count": len(canonical),
        "noncanonical_rich_line_count": len(noncanonical),
        "maximum_canonical_line_incidence": max(
            canonical, default=2
        ),
        "maximum_noncanonical_line_incidence": max(
            noncanonical, default=2
        ),
    }


def block_line_clusters(
    prime: int,
    sources: tuple[int, ...],
    selected: tuple[int, ...],
) -> list[dict[str, object]]:
    groups: dict[
        tuple[tuple[int, ...], ...], list[tuple[int, ...]]
    ] = defaultdict(list)
    for block in itertools.combinations(selected, len(sources)):
        groups[line_key(prime, sources, block)].append(block)

    clusters = []
    for blocks in groups.values():
        if len(blocks) < 2:
            continue
        root_sets = [set(block) for block in blocks]
        pairwise_disjoint = all(
            root_sets[left].isdisjoint(root_sets[right])
            for left in range(len(root_sets))
            for right in range(left + 1, len(root_sets))
        )
        vertices = sorted(
            {
                tuple(value for value in block if value != omitted)
                for block in blocks
                for omitted in block
            }
        )
        clusters.append(
            {
                "blocks": blocks,
                "vertices": vertices,
                "pairwise_disjoint": pairwise_disjoint,
            }
        )
    return clusters


def relation_accounting(
    prime: int,
    sources: tuple[int, ...],
    selected: tuple[int, ...],
) -> dict[str, object]:
    labels, matrix = evaluation_matrix(prime, sources, selected)
    label_index = {label: index for index, label in enumerate(labels)}
    point_count = len(labels)
    global_defect = point_count - rank_mod(matrix, prime)
    generated: list[list[int]] = []
    cluster_rows = []

    for cluster in block_line_clusters(prime, sources, selected):
        require(
            cluster['pairwise_disjoint'],
            'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:278',
        )
        indices = [label_index[label] for label in cluster["vertices"]]
        local_matrix = [matrix[index] for index in indices]
        local_basis = nullspace_basis(transpose(local_matrix), prime)
        for local_vector in local_basis:
            embedded = [0] * point_count
            for index, value in zip(indices, local_vector):
                embedded[index] = value
            require(
                all((sum((coefficient * entry for coefficient, entry in zip(embedded, column))) % prime == 0 for column in transpose(matrix))),
                'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:286',
            )
            generated.append(embedded)
        cluster_rows.append(
            {
                "block_count": len(cluster["blocks"]),
                "vertex_count": len(indices),
                "local_relation_dimension": len(local_basis),
                "pairwise_disjoint": cluster["pairwise_disjoint"],
            }
        )

    generated_dimension = rank_mod(generated, prime)
    require(
        generated_dimension <= global_defect,
        'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:306',
    )
    return {
        "rank": point_count - global_defect,
        "point_count": point_count,
        "global_relation_dimension": global_defect,
        "block_line_generated_dimension": generated_dimension,
        "non_block_line_quotient_dimension": (
            global_defect - generated_dimension
        ),
        "coincident_line_clusters": cluster_rows,
    }


def characteristic_13_census() -> dict[str, object]:
    prime = 13
    field = set(range(prime))
    signature_counts: Counter[tuple[int, int]] = Counter()
    maximum_cluster_blocks = 0
    maximum_canonical_line_incidence = 0
    maximum_noncanonical_line_incidence = 0
    tested = 0
    for sources in itertools.combinations(range(1, prime), 4):
        selected = tuple(sorted(field - set(sources) - {0}))
        row = relation_accounting(prime, sources, selected)
        signature_counts[
            (
                row["global_relation_dimension"],
                row["block_line_generated_dimension"],
            )
        ] += 1
        maximum_cluster_blocks = max(
            maximum_cluster_blocks,
            max(
                (
                    cluster["block_count"]
                    for cluster in row["coincident_line_clusters"]
                ),
                default=1,
            ),
        )
        require(
            row['non_block_line_quotient_dimension'] == 0,
            'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:346',
        )
        rich_profile = rich_line_profile(prime, sources, selected)
        maximum_canonical_line_incidence = max(
            maximum_canonical_line_incidence,
            rich_profile["maximum_canonical_line_incidence"],
        )
        maximum_noncanonical_line_incidence = max(
            maximum_noncanonical_line_incidence,
            rich_profile["maximum_noncanonical_line_incidence"],
        )
        tested += 1
    return {
        "prime": prime,
        "a": 4,
        "R": 8,
        "tested": tested,
        "relation_signature_counts": {
            f"global_{global_dimension}_block_{block_dimension}": count
            for (global_dimension, block_dimension), count in sorted(
                signature_counts.items()
            )
        },
        "maximum_coincident_block_count": maximum_cluster_blocks,
        "maximum_canonical_line_incidence": (
            maximum_canonical_line_incidence
        ),
        "maximum_noncanonical_line_incidence": (
            maximum_noncanonical_line_incidence
        ),
        "non_block_line_quotient_maximum": 0,
    }


def characteristic_13_noncanonical_threshold_census() -> dict[str, object]:
    prime = 13
    field = set(range(prime))
    rank_counts: Counter[int] = Counter()
    line_signature_counts: Counter[tuple[int, int]] = Counter()
    tested = 0
    for sources in itertools.combinations(range(prime), 4):
        selected = tuple(sorted(field - set(sources)))
        _, matrix = evaluation_matrix(prime, sources, selected)
        rank_counts[rank_mod(matrix, prime)] += 1
        rich = rich_line_profile(prime, sources, selected)
        line_signature_counts[
            (
                rich["maximum_canonical_line_incidence"],
                rich["maximum_noncanonical_line_incidence"],
            )
        ] += 1
        tested += 1
    return {
        "prime": prime,
        "a": 4,
        "R": 9,
        "point_count": comb(9, 3),
        "postcritical_degree": 7,
        "canonical_line_capacity": 8,
        "line_relation_threshold": 9,
        "tested": tested,
        "rank_counts": {
            str(rank): count for rank, count in sorted(rank_counts.items())
        },
        "line_signature_counts": {
            f"canonical_{canonical}_noncanonical_{noncanonical}": count
            for (canonical, noncanonical), count in sorted(
                line_signature_counts.items()
            )
        },
        "maximum_noncanonical_line_incidence": max(
            noncanonical
            for _, noncanonical in line_signature_counts
        ),
        "rank_deficient_configurations": sum(
            count
            for rank, count in rank_counts.items()
            if rank != comb(9, 3)
        ),
    }


