def diagonal_cauchy_normal_form_regression() -> dict[str, object]:
    prime = 101
    sources = (0, 1, 2, 3, 4)
    beta = (10, 11, 12, 13, 14)
    scales = (1, 2, 3, 4, 5)
    test_t = (20, 21, 22, 23, 24)
    test_lambda = (30, 31, 32, 33, 34)
    scale_product = product_mod(scales, prime)

    def lagrange_value(index: int, value: int) -> int:
        numerator = product_mod(
            (
                (value - source) % prime
                for position, source in enumerate(sources)
                if position != index
            ),
            prime,
        )
        denominator = product_mod(
            (
                (sources[index] - source) % prime
                for position, source in enumerate(sources)
                if position != index
            ),
            prime,
        )
        return numerator * pow(denominator, prime - 2, prime) % prime

    def direct_value(t_value: int, lambda_value: int) -> int:
        return sum(
            lagrange_value(index, t_value)
            * product_mod(
                (
                    scales[position]
                    * (lambda_value - beta[position])
                    for position in range(len(sources))
                    if position != index
                ),
                prime,
            )
            for index in range(len(sources))
        ) % prime

    def cauchy_value(t_value: int, lambda_value: int) -> int:
        source_product = product_mod(
            ((t_value - source) for source in sources), prime
        )
        beta_product = product_mod(
            ((lambda_value - root) for root in beta), prime
        )
        diagonal_sum = 0
        for index, source in enumerate(sources):
            source_derivative = product_mod(
                (
                    (source - other) % prime
                    for position, other in enumerate(sources)
                    if position != index
                ),
                prime,
            )
            weight = (
                scale_product
                * pow(scales[index], prime - 2, prime)
                * pow(source_derivative, prime - 2, prime)
            ) % prime
            denominator = (
                (t_value - source)
                * (lambda_value - beta[index])
            ) % prime
            diagonal_sum += weight * pow(denominator, prime - 2, prime)
        return source_product * beta_product * diagonal_sum % prime

    matrix = [
        [direct_value(t_value, lambda_value) for lambda_value in test_lambda]
        for t_value in test_t
    ]
    checked_pairs = 0
    for t_value in test_t:
        for lambda_value in test_lambda:
            require(
                direct_value(t_value, lambda_value) == cauchy_value(t_value, lambda_value),
                'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:591',
            )
            checked_pairs += 1
    return {
        "prime": prime,
        "a": len(sources),
        "checked_pairs": checked_pairs,
        "evaluation_matrix_rank": rank_mod(matrix, prime),
        "expected_full_rank": len(sources),
    }


def koalabear_block_line_table() -> list[dict[str, int | bool]]:
    rows = []
    for a in range(12, 17):
        for regular_count in range(53 + a, 70):
            degree = regular_count - a + 2
            maximum_blocks = regular_count // a
            remainder = regular_count % a
            near_full_allowance = int(remainder == a - 1)
            maximum_vertices = (
                a * maximum_blocks + near_full_allowance
            )
            overload_threshold = degree + 2
            conic_circuit_support = 2 * degree + 2
            cubic_circuit_support = 3 * degree
            minimum_support_deficit = (a - 4) * (a - 1)
            rows.append(
                {
                    "a": a,
                    "R": regular_count,
                    "postcritical_degree": degree,
                    "maximum_disjoint_blocks": maximum_blocks,
                    "near_full_fiber_allowance": near_full_allowance,
                    "maximum_canonical_line_vertices": maximum_vertices,
                    "overload_threshold": overload_threshold,
                    "low_support_line_cutoff": 2 * degree + 1,
                    "block_line_overload_possible": (
                        maximum_vertices >= overload_threshold
                    ),
                    "maximum_forced_relation_dimension": max(
                        0, maximum_vertices - (degree + 1)
                    ),
                    "minimum_support_no_common_root_deficit": (
                        minimum_support_deficit
                    ),
                    "minimum_roots_of_multiplicity_at_least_a_minus_2": max(
                        0,
                        regular_count
                        - minimum_support_deficit // 2,
                    ),
                    "minimum_overload_grs_length": overload_threshold,
                    "minimum_overload_grs_dimension": a,
                    "minimum_overload_grs_distance": (
                        overload_threshold - a + 1
                    ),
                    "minimum_overload_grs_total_weight_excess": (
                        minimum_support_deficit
                    ),
                    "conic_circuit_support": conic_circuit_support,
                    "reducible_conic_component_load": degree + 1,
                    "both_reducible_conic_components_can_be_canonical": (
                        maximum_vertices >= degree + 1
                    ),
                    "cubic_complete_intersection_support": (
                        cubic_circuit_support
                    ),
                    "first_unclassified_circuit_support": (
                        cubic_circuit_support + 1
                    ),
                }
            )
    return rows


