def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--emit", action="store_true")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--tamper-selftest", action="store_true")
    args = parser.parse_args()

    data = payload()
    validate(data)
    if args.emit:
        CERTIFICATE.write_text(
            json.dumps(data, indent=2, sort_keys=True) + "\n"
        )
    if args.check:
        require(
            json.loads(CERTIFICATE.read_text()) == data,
            'verification condition failed at experimental/notes/frontier-adjacent/kb_mca_v4_equality_wall_geometry_v1/verification/verify_postcritical_block_line_relation_space.py:864',
        )
    if args.tamper_selftest:
        tampered = json.loads(json.dumps(data))
        hardest = next(
            row
            for row in tampered["koalabear_block_line_capacity"]
            if row["a"] == 12 and row["R"] == 69
        )
        hardest["block_line_overload_possible"] = True
        try:
            validate(tampered)
        except VerificationError:
            pass
        else:
            raise VerificationError("tamper was not rejected")

    print("characteristic-13 relation quotient census: PASS")
    print("cross-characteristic relation generation: PASS")
    print("KoalaBear block-line capacity: PASS")
    print("diagonal Cauchy normal form: PASS")
    print("Cayley-Bacharach circuit arithmetic: PASS")
    print(f"payload_sha256={data['payload_sha256']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
